export default function EventCard({ title, category, date, location, image }) {
  return (
    <div className="bg-white rounded-xl shadow-md overflow-hidden hover:shadow-lg transition-shadow cursor-pointer">
      <div className="h-40 bg-gray-200 flex items-center justify-center">
        <span className="text-gray-400 text-sm">Event Image</span>
      </div>
      <div className="p-4">
        <span className="text-xs font-medium text-blue-600 bg-blue-50 px-2 py-1 rounded-full">
          {category}
        </span>
        <h3 className="text-lg font-semibold mt-2">{title}</h3>
        <p className="text-sm text-gray-500 mt-1">{date}</p>
        <p className="text-sm text-gray-500">{location}</p>
      </div>
    </div>
  )
}